  `insurance_money` int NOT NULL DEFAULT '0' COMMENT '保费',
  `fba_shipment_id` char(32) NOT NULL DEFAULT '',
  `amaz_order_id` char(32) NOT NULL DEFAULT '',
  `scan_file` tinyint NOT NULL DEFAULT '0',
  `carry_name` char(64) NOT NULL DEFAULT '',
  `shipment_service_level` char(128) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '',
  `latest_ship_time` int NOT NULL DEFAULT '0',
  `note` varchar(1024) NOT NULL DEFAULT '',
  `customer_notes` varchar(1024) NOT NULL DEFAULT '',
  `origin_scan_date` char(32) NOT NULL DEFAULT '',
  `lpn` char(64) NOT NULL DEFAULT '',
  `shipping_method` varchar(512) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '',
  `cost` int NOT NULL DEFAULT '0',
  `ups_capital` tinyint NOT NULL DEFAULT '0',
  `box_size` char(64) NOT NULL DEFAULT '',
  `ship_channel` char(32) NOT NULL DEFAULT '',
  `pause_note` char(255) NOT NULL DEFAULT '',
  `pause_reason` tinyint NOT NULL DEFAULT '0',
  `outbound_co_id` int NOT NULL DEFAULT '0',
  `export_group_id` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`outbound_id`),
  KEY `uid_key` (`uid`),
  KEY `update_key` (`last_update_time`),
  KEY `SELECT_KEY` (`outbound_sn`,`create_time`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;
